/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let result = 'empty';
	if(event.payload.item && event.payload.item.class){
		result = event.payload.item.class;
	}
	return {
				event: "Unified Map Search Requested",
				value: {searchedClass: result}
			};
}

/**
* @param {params} params
