/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let level = event.payload.value;
	return {
		event: "Unified Map Level Selected",
		value: {selectedLevel: level}
	};
}
